import json, random, datetime
from typing import Any, Dict

EMPTY_MARKS = ('', '待补充', '系统待生成', '无', '暂无')
FUSION_PRODUCT_TYPES = ('家庭基础套餐',)
BASE_FIELDS = (
    ('name', '销售品名称'), ('product_type', '产品类型'), ('series', '所属系列'),
    ('price', '套餐档位（月费）'), ('resources', '套内资源'), ('out_price', '套外资费'),
    ('billing_cycle', '计费周期'), ('effective_way', '生效方式'), ('validity', '套餐有效期'),
    ('change_rule', '变更规则'), ('cancel_rule', '退订/拆机规则'),
)
FUSION_EXTRA_FIELDS = (('members', '融合成员'),)
PRICE_FIELDS = ('price',)
REQUIRED_FIELDS = ('price', 'resources')

def _norm(v):
    if v is None:
        return ''
    if isinstance(v, bool):
        return '是' if v else '否'
    if isinstance(v, (int, float)):
        return v
    s = str(v).strip()
    return '' if s in EMPTY_MARKS else s

def _gen_req_id():
    ts = datetime.datetime.now().strftime('%Y%m%d%H%M%S')
    return 'PLAN%s%03d' % (ts, random.randint(0, 999))

def fields_for(product_type):
    if _norm(product_type) in FUSION_PRODUCT_TYPES:
        return BASE_FIELDS + FUSION_EXTRA_FIELDS
    return BASE_FIELDS

async def main(args):
    p = args.params
    raw = p.get('elements_json') or ''
    elements = {}
    if isinstance(raw, str) and raw.strip():
        try:
            elements = json.loads(raw)
        except Exception:
            try:
                t = raw.strip()
                if ':' in t and not t.startswith('{') and not t.startswith('['):
                    t = t.split(':', 1)[1].strip()
                elements = json.loads(t)
            except Exception:
                elements = {}
    elif isinstance(raw, dict):
        elements = raw
    req_id = str(p.get('req_id') or _gen_req_id())
    reporter = str(p.get('reporter') or '')
    need_summary = str(p.get('need_summary') or '')
    today = datetime.date.today().strftime('%Y-%m-%d')
    fmt = lambda k: _norm(elements.get(k))
    fields = fields_for(elements.get('product_type'))
    values = {}
    pending = []
    for key, label in fields:
        val = fmt(key)
        values[key] = val
        if key in REQUIRED_FIELDS and (val == '' or (key in PRICE_FIELDS and val in (0, '0', '0元'))):
            pending.append(label)
    def cell(v):
        return '待补充' if v == '' else str(v)
    lines = []
    lines.append('## 销售品需求提报单')
    base_rows = [('需求单号', req_id), ('提报日期', today)]
    if reporter:
        base_rows.append(('提报人', reporter))
    if need_summary:
        base_rows.append(('需求概述', need_summary))
    prod_rows = [('销售品名称', cell(values['name'])), ('产品类型', cell(values['product_type']))]
    if values['series']:
        prod_rows.append(('所属系列', values['series']))
    if values.get('members'):
        prod_rows.append(('融合成员', values['members']))
    fee_rows = [('套餐档位（月费）', (values['price'] + ' 元/月') if values['price'] != '' else '待补充')]
    if values['resources']:
        fee_rows.append(('套内资源', values['resources']))
    if values['out_price']:
        fee_rows.append(('套外资费', values['out_price']))
    if values['billing_cycle']:
        fee_rows.append(('计费周期', values['billing_cycle']))
    order_rows = []
    if values['effective_way']:
        order_rows.append(('生效方式', values['effective_way']))
    if values['validity']:
        order_rows.append(('套餐有效期', values['validity']))
    if values['change_rule']:
        order_rows.append(('变更规则', values['change_rule']))
    if values['cancel_rule']:
        order_rows.append(('退订/拆机规则', values['cancel_rule']))
    def table(rows):
        if not rows:
            return []
        out = ['| 字段 | 内容 |', '| --- | --- |']
        out += ['| %s | %s |' % (k, v) for k, v in rows]
        return out
    lines.append('### 1. 需求基本信息')
    lines += table(base_rows)
    lines.append('')
    lines.append('### 2. 产品/销售品信息')
    lines += table(prod_rows)
    lines.append('')
    lines.append('### 3. 资费方案要点')
    lines += table(fee_rows)
    lines.append('')
    lines.append('### 4. 订购/变更/退订规则')
    if order_rows:
        lines += table(order_rows)
    else:
        lines.append('（未提及，从宽不催补）')
    lines.append('')
    lines.append('### 5. 待补充字段')
    lines.append('、'.join(pending) if pending else '无')
    while lines and lines[-1] == '':
        lines.pop()
    text = '\n'.join(lines)
    ret: Output = {
        "report_text": text,
        "pending_fields": ','.join(pending),
        "pending_count": (str(len(pending)) if pending else ''),
        "req_id": req_id,
        "elements": json.dumps(values, ensure_ascii=False),
    }
    return ret

